INSERT INTO `job_posts` (`employer_id`,`store_id`,`title`,`job_description`,`requirements`,`benefits`,`hourly_wage_min`,`hourly_wage_max`,`currency`,`vacancy_count`,`min_age`,`max_age`,`gender_requirement`,`employment_type`,`status`,`moderation_blocked`,`published_at`,`expired_at`,`created_at`,`updated_at`) VALUES (@demo_0114,@demo_0157,'Phục vụ cuối tuần - Mây Sớm Coffee [Demo 01]','Tham gia đội ngũ Mây Sớm Coffee ở vị trí phục vụ. Chuẩn bị khu vực làm việc, phối hợp cùng trưởng ca, hỗ trợ khách hàng và bàn giao cuối ca. Đây là tin giả lập dành riêng cho kiểm thử, không phải cơ hội tuyển dụng thật.','Từ 18 tuổi; đúng giờ, giao tiếp lịch sự, sẵn sàng học hỏi. Đăng ký tối thiểu 3 ca/tuần; ưu tiên lịch ổn định trong 2 tháng.','Đào tạo đầu vào, chủ động đăng ký ca học phù hợp, hỗ trợ bữa ăn và hướng dẫn công việc rõ ràng. Quyền lợi chỉ mang tính minh họa.',23000,30000,'VND',2,18,35,'ANY','PART_TIME','ACTIVE',0,TIMESTAMP(DATE_ADD(@demo_reference_date,INTERVAL -83 DAY),'09:00:00'),TIMESTAMP(DATE_ADD(@demo_reference_date,INTERVAL 3 DAY),'09:00:00'),TIMESTAMP(DATE_ADD(@demo_reference_date,INTERVAL -84 DAY),'09:00:00'),TIMESTAMP(DATE_ADD(@demo_reference_date,INTERVAL -83 DAY),'09:00:00'));
